package br.com.sussmartcare.queue.infrastructure.messaging; import br.com.sussmartcare.queue.application.QueueApplicationService; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.*; import org.springframework.stereotype.Component; @Component @EnableScheduling public class QueueReturnPolicyScheduler {private final QueueApplicationService app;private final int threshold;private final long expected;private final long grace;public QueueReturnPolicyScheduler(QueueApplicationService a,@Value("${queue.return.position-threshold:3}")int t,@Value("${queue.return.expected-minutes:15}")long e,@Value("${queue.return.grace-minutes:10}")long g){app=a;threshold=t;expected=e;grace=g;}@Scheduled(fixedDelayString="${queue.return.policy-delay-ms:30000}")public void evaluate(){app.evaluateReturnPolicies(threshold,expected,grace);}}
